"""Writes tools/stats/cases_t9.txt: createns, ExhaustiveSearcher, KDTreeSearcher and their methods."""
import os
here = os.path.dirname(os.path.abspath(__file__))
PRE = "X=[x(1:20)' y(1:20)']; Y=[x(21:25)' y(21:25)']; "
L = ["# generated by make_t9_cases.py"]
def add(cs, fmt):
    for c in cs:
        L.append(fmt.replace("{c}", c))
EP = "{m.X, m.Distance, m.DistParameter}"
KP = "{m.X, m.Distance, m.DistParameter, m.BucketSize}"
add(["createns(X)", "createns(X,'NSMethod','exhaustive')", "createns(X,'NSMethod','kdtree')", "createns(X,'Distance','cityblock')", "createns(X,'Distance','chebychev')", "createns(X,'Distance','minkowski','P',3)", "createns(X,'Distance','mahalanobis')", "createns(X,'Distance','seuclidean')", "createns(X,'Distance','cosine')",
     "createns(X,'NSMethod','kdtree','BucketSize',5)", "createns(X,'NSMethod','exhaustive','Distance','correlation')", "ExhaustiveSearcher(X)", "ExhaustiveSearcher(X,'Distance','cityblock')", "ExhaustiveSearcher(X,'Distance','minkowski','P',4)", "ExhaustiveSearcher(X,'Distance','mahalanobis','Cov',[2 0.3;0.3 1])", "ExhaustiveSearcher(X,'Distance','seuclidean','Scale',[1 2])"],
    "m = {c}; r = " + EP + ";")
add(["KDTreeSearcher(X)", "KDTreeSearcher(X,'Distance','cityblock')", "KDTreeSearcher(X,'BucketSize',3)", "KDTreeSearcher(X,'Distance','minkowski','P',3)", "KDTreeSearcher(X,'Distance','chebychev')", "createns(X,'NSMethod','kdtree','Distance','chebychev')"], "m = {c}; r = " + KP + ";")
add(["createns(X,'Foo',1)", "createns(X,'NSMethod','foo')", "createns(X,'NSMethod','kdtree','Distance','cosine')", "createns(X,'Distance','foo')", "createns()", "ExhaustiveSearcher()", "ExhaustiveSearcher(X,'Foo',1)", "KDTreeSearcher(X,'Distance','cosine')", "KDTreeSearcher(X,'BucketSize',0)", "createns([X;NaN 1])", "createns(X,'Distance','minkowski','P',-1)",
     "createns(X,'BucketSize',5)", "ExhaustiveSearcher(X,'BucketSize',5)"], "m = {c}; r = 1;")
add(["createns(X)", "createns(X,'Distance','cityblock')", "ExhaustiveSearcher(X,'Distance','chebychev')", "KDTreeSearcher(X)", "KDTreeSearcher(X,'Distance','cityblock')", "createns(X,'Distance','mahalanobis')", "createns(X,'Distance','cosine')"],
    "m = {c}; [i_,d_] = knnsearch(m,Y,'K',3); r = {i_,d_};")
add(["createns(X)", "createns(X,'Distance','cityblock')", "ExhaustiveSearcher(X,'Distance','chebychev')", "KDTreeSearcher(X)", "createns(X,'Distance','cosine')"],
    "m = {c}; [i_,d_] = rangesearch(m,Y,0.8); r = {cellfun(@numel,i_), [i_{:}], [d_{:}]};")
add(["knnsearch(m,Y)", "knnsearch(m,Y,'K',2,'IncludeTies',true)", "knnsearch(m,Y(:,1))", "knnsearch(m)", "rangesearch(m,Y)", "rangesearch(m,Y,-1)", "knnsearch(m,Y,'K',0)", "knnsearch(m,Y,'Distance','cityblock')", "knnsearch(m,Y,'Foo',1)"], "m = createns(X); r = {c};")
L = [L[0]] + [PRE + l for l in L[1:]]
with open(os.path.join(here, "cases_t9.txt"), "w", encoding="utf-8", newline="\n") as f:
    f.write("\n".join(L) + "\n")
print(len(L))
